function [h, found, refused] = st_head(q_st, valid, n_heads, tol)
%ST_HEAD  The head the filter starts from: the first configured head whose reading is plausible; refused counts the heads that
%   flagged a valid frame whose quaternion was not (the tick counts them).
%   q_st: real[1][4][2] (passed a plain number)
%   valid: bool[2] (passed true or false)
%   n_heads: int (passed a whole number)
%   tol: real[1] (passed a plain number)
%   returns h: int (passed a whole number)
%   returns found: bool (passed true or false)
%   returns refused: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    h = 0;
    found = false;
    refused = 0;
    h = 0;
    found = false;
    refused = 0;
    t__1 = ((0):((n_heads) - 1)).';
    for k = t__1(logical(valid((t__1) + 1))).'
        if asils.alg.estimation.st_plausible((q_st((k) + 1, :)).', valid((k) + 1), k, n_heads, tol)
            if (~found)
                h = k;
